function f(n){return n.length===0?0:n.reduce((r,e)=>r+e,0)/n.length}function M(n){const r=n.length;if(r===0)return{slope:0,intercept:0};const e=(r-1)/2,c=f(n);let u=0,l=0;for(let a=0;a<r;a++){const i=a-e,m=n[a]-c;u+=i*m,l+=i*i}const s=l===0?0:u/l,d=c-s*e;return{slope:s,intercept:d}}function B(n,r){if(n.length===0)return{data:[],meta:{intervalMs:36e5,slope:0,stdev:0}};const e=n.map(t=>new Date(t.time).getTime()).filter(t=>Number.isFinite(t)),c=n.map(t=>t.value),u=e[e.length-1]||Date.now(),l=e.length>=2?Math.max(1,e[e.length-1]-e[e.length-2]):36e5,{slope:s,intercept:d}=M(c),a=c.map((t,o)=>t-(d+s*o)),i=f(a),m=a.length?a.reduce((t,o)=>t+Math.pow(o-i,2),0)/a.length:0,p=Math.sqrt(m),h=n.map((t,o)=>({time:new Date(e[o]||u).toISOString(),actual:t.value,predicted:t.value,upperBound:t.value,lowerBound:t.value})),v=c.length;for(let t=1;t<=r;t++){const o=d+s*(v-1+t),g=p*Math.sqrt(t+1),w=u+l*t;h.push({time:new Date(w).toISOString(),actual:null,predicted:o,upperBound:o+g,lowerBound:o-g})}return{data:h,meta:{intervalMs:l,slope:s,stdev:p}}}export{B as b};
